∀ {capability : ASPProof.ActivationRepairTransaction.RepairCapability}
  {proposal : ASPProof.ActivationRepairTransaction.RepairProposal}
  {head : ASPProof.ActivationRepairTransaction.RepairHead}
  (proof : ASPProof.ActivationRepairTransaction.CanCommitRepair capability proposal head),
  (ASPProof.ActivationRepairTransaction.commitRepair capability proposal head proof).state.declaredGeneration =
    proposal.targetGeneration

∀ {capability : ASPProof.ActivationRepairTransaction.RepairCapability}
  {proposal : ASPProof.ActivationRepairTransaction.RepairProposal}
  {head : ASPProof.ActivationRepairTransaction.RepairHead}
  (proof : ASPProof.ActivationRepairTransaction.CanCommitRepair capability proposal head),
  (ASPProof.ActivationRepairTransaction.commitRepair capability proposal head proof).authorityRevision =
    head.authorityRevision + 1

∀ {capability : ASPProof.ActivationRepairTransaction.RepairCapability}
  {proposal : ASPProof.ActivationRepairTransaction.RepairProposal}
  {head : ASPProof.ActivationRepairTransaction.RepairHead}
  (proof : ASPProof.ActivationRepairTransaction.CanCommitRepair capability proposal head),
  (ASPProof.ActivationRepairTransaction.commitRepair capability proposal head proof).canonicalIdentity =
    head.canonicalIdentity

