  (proof : ASPProof.ActivationRepairTransaction.CanCommitRepair capability proposal head),
  (ASPProof.ActivationRepairTransaction.commitRepair capability proposal head proof).state.phase =
    ASPProof.ActivationLifecycleAudit.ActivationPhase.activating

